UPDATE schema_migrations SET applied_at=substr(strftime('%Y-%m-%dT%H:%M:%fZ',applied_at),1,23)||'000000Z';
UPDATE workspaces SET first_seen_at=substr(strftime('%Y-%m-%dT%H:%M:%fZ',first_seen_at),1,23)||'000000Z',last_seen_at=substr(strftime('%Y-%m-%dT%H:%M:%fZ',last_seen_at),1,23)||'000000Z',last_reconciled_at=substr(strftime('%Y-%m-%dT%H:%M:%fZ',last_reconciled_at),1,23)||'000000Z';
UPDATE repositories SET first_seen_at=substr(strftime('%Y-%m-%dT%H:%M:%fZ',first_seen_at),1,23)||'000000Z',last_seen_at=substr(strftime('%Y-%m-%dT%H:%M:%fZ',last_seen_at),1,23)||'000000Z',last_leased_at=CASE WHEN last_leased_at IS NULL THEN NULL ELSE substr(strftime('%Y-%m-%dT%H:%M:%fZ',last_leased_at),1,23)||'000000Z' END;
UPDATE slots SET created_at=substr(strftime('%Y-%m-%dT%H:%M:%fZ',created_at),1,23)||'000000Z',updated_at=substr(strftime('%Y-%m-%dT%H:%M:%fZ',updated_at),1,23)||'000000Z',ready_at=CASE WHEN ready_at IS NULL THEN NULL ELSE substr(strftime('%Y-%m-%dT%H:%M:%fZ',ready_at),1,23)||'000000Z' END,last_used_at=CASE WHEN last_used_at IS NULL THEN NULL ELSE substr(strftime('%Y-%m-%dT%H:%M:%fZ',last_used_at),1,23)||'000000Z' END;
UPDATE sessions SET created_at=substr(strftime('%Y-%m-%dT%H:%M:%fZ',created_at),1,23)||'000000Z',started_at=CASE WHEN started_at IS NULL THEN NULL ELSE substr(strftime('%Y-%m-%dT%H:%M:%fZ',started_at),1,23)||'000000Z' END,released_at=CASE WHEN released_at IS NULL THEN NULL ELSE substr(strftime('%Y-%m-%dT%H:%M:%fZ',released_at),1,23)||'000000Z' END,archived_at=CASE WHEN archived_at IS NULL THEN NULL ELSE substr(strftime('%Y-%m-%dT%H:%M:%fZ',archived_at),1,23)||'000000Z' END,expires_at=CASE WHEN expires_at IS NULL THEN NULL ELSE substr(strftime('%Y-%m-%dT%H:%M:%fZ',expires_at),1,23)||'000000Z' END,last_heartbeat_at=CASE WHEN last_heartbeat_at IS NULL THEN NULL ELSE substr(strftime('%Y-%m-%dT%H:%M:%fZ',last_heartbeat_at),1,23)||'000000Z' END;
UPDATE snapshots SET created_at=substr(strftime('%Y-%m-%dT%H:%M:%fZ',created_at),1,23)||'000000Z',expires_at=substr(strftime('%Y-%m-%dT%H:%M:%fZ',expires_at),1,23)||'000000Z';
UPDATE jobs SET not_before=CASE WHEN not_before IS NULL THEN NULL ELSE substr(strftime('%Y-%m-%dT%H:%M:%fZ',not_before),1,23)||'000000Z' END,started_at=CASE WHEN started_at IS NULL THEN NULL ELSE substr(strftime('%Y-%m-%dT%H:%M:%fZ',started_at),1,23)||'000000Z' END,finished_at=CASE WHEN finished_at IS NULL THEN NULL ELSE substr(strftime('%Y-%m-%dT%H:%M:%fZ',finished_at),1,23)||'000000Z' END,lease_expires_at=CASE WHEN lease_expires_at IS NULL THEN NULL ELSE substr(strftime('%Y-%m-%dT%H:%M:%fZ',lease_expires_at),1,23)||'000000Z' END;
UPDATE events SET time=substr(strftime('%Y-%m-%dT%H:%M:%fZ',time),1,23)||'000000Z';
